(() => {
  const clean = (s) => ((s || '') + '').trim();
  const 行 = [...document.querySelectorAll('.annex-item')].find((e) => clean(e.innerText).includes('AIGC生成师'));
  if (!行) return '没有 AIGC 那一行';
  const 钮 = 行.querySelector('[ka=side_delete_attachment_btn_click]');
  if (!钮) return 'AIGC 行里没找到删除钮';
  [...document.querySelectorAll('[data-orca-tag]')].forEach((x) => x.removeAttribute('data-orca-tag'));
  行.setAttribute('data-orca-tag', 'row');
  钮.setAttribute('data-orca-tag', 'hit');
  return '打上了：行 + 删除钮（删除钮宽=' + Math.round(钮.getBoundingClientRect().width) + '）';
})()

(() => {
  const clean = (s) => ((s || '') + '').trim();
  const vis = (e) => { const r = e.getBoundingClientRect(); return r.width > 2 && r.height > 2; };
  const d = [...document.querySelectorAll('[class*=dialog]')].filter((e) => vis(e) && clean(e.innerText).length > 2);
  return {弹窗: d.map((e) => (e.className || '').toString().slice(0, 30) + ':' + clean(e.innerText).slice(0, 80)).slice(0, 3)};
})()

